<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppHeader from '../../components/AppHeader.vue'
import BottomAction from '../../components/BottomAction.vue'
import { useAppStore } from '../../stores/app'
import { go } from '../../utils/ui'
const store=useAppStore(); const id=ref(''); const editing=computed(()=>Boolean(id.value))
const tomorrow=new Date(Date.now()+86400000); const date=tomorrow.toISOString().slice(0,10)
const form=reactive({title:'',type:'RATED',format:'SINGLE_ELIMINATION',scope:'PUBLIC',review:false,maxParticipants:16,bestOf:5,location:'',registrationDate:date,startDate:date,description:''})
const types=[['RATED','积分赛'],['DAILY','日常赛'],['EXAM','考试']]; const formats=[['SINGLE_ELIMINATION','单淘汰'],['ROUND_ROBIN','小组循环']]
onLoad(async q=>{id.value=String(q?.id||''); if(!id.value)return; await store.selectCompetition(id.value); const d:any=store.selectedCompetition;if(!d)return; Object.assign(form,{title:d.title,type:d.competition_type||d.type,format:d.format,scope:d.registration_scope||'PUBLIC',review:Boolean(d.registration_requires_review),maxParticipants:d.max_participants||16,bestOf:d.best_of||5,location:d.location||'',registrationDate:String(d.registration_end||date).slice(0,10),startDate:String(d.start_time||date).slice(0,10),description:d.description||''})})
async function submit(){if(!form.title.trim()||!form.location.trim())return uni.showToast({title:'请填写名称和地点',icon:'none'}); const payload={title:form.title.trim(),description:form.description,type:form.type,format:form.format,scope:form.scope,review:form.review,maxParticipants:Number(form.maxParticipants),bestOf:Number(form.bestOf),location:form.location.trim(),registrationStart:new Date().toISOString(),registrationEnd:new Date(`${form.registrationDate}T23:00:00+08:00`).toISOString(),startTime:new Date(`${form.startDate}T19:00:00+08:00`).toISOString()}; try{if(editing.value)await store.updateCompetition(id.value,payload);else await store.createCompetition(form.format as any,payload); go('/pages/competition/manage',{id:id.value||store.selectedCompetitionId})}catch{}}
</script>
<template><view class="app-shell no-tabs form-page"><AppHeader :title="editing?'编辑比赛':'创建比赛'" backable/><view class="field"><text class="field-label">比赛名称</text><input v-model="form.title" class="input" placeholder="例如：2026 秋季积分赛"/></view><view class="field"><text class="field-label">比赛性质</text><view class="segment"><button v-for="item in types" :key="item[0]" :class="['segment-item',{active:form.type===item[0]}]" @click="form.type=item[0]">{{ item[1] }}</button></view></view><view class="field"><text class="field-label">赛制（V1 固定单打）</text><view class="segment"><button v-for="item in formats" :key="item[0]" :class="['segment-item',{active:form.format===item[0]}]" @click="form.format=item[0]">{{ item[1] }}</button></view></view><view class="grid-two"><view class="field"><text class="field-label">人数上限</text><input v-model.number="form.maxParticipants" class="input" type="number"/></view><view class="field"><text class="field-label">局制</text><picker :range="[3,5,7]" @change="form.bestOf=[3,5,7][Number($event.detail.value)]"><view class="select-field">{{ form.bestOf }} 局</view></picker></view></view><view class="field"><text class="field-label">地点</text><input v-model="form.location" class="input" placeholder="体育馆三楼"/></view><view class="grid-two"><view class="field"><text class="field-label">报名截止</text><picker mode="date" :value="form.registrationDate" @change="form.registrationDate=$event.detail.value"><view class="select-field">{{ form.registrationDate }}</view></picker></view><view class="field"><text class="field-label">比赛日期</text><picker mode="date" :value="form.startDate" @change="form.startDate=$event.detail.value"><view class="select-field">{{ form.startDate }}</view></picker></view></view><view class="field"><text class="field-label">比赛说明</text><textarea v-model="form.description" class="textarea" placeholder="赛程安排、注意事项等"/></view><view v-if="store.error" class="notice notice-error">{{ store.error }}</view><BottomAction><button class="btn btn-primary btn-block" :disabled="store.loading" @click="submit">{{ store.loading?'保存中…':editing?'保存修改':'创建比赛' }}</button></BottomAction></view></template>
<style scoped>.form-page{padding-bottom:6rem}.field{margin-top:1rem}.grid-two .field{min-width:0}</style>
